  7	function usage(programName) {
  8	  return `usage: ${programName} [-h] --subject SUBJECT --user_data USER_DATA`;
  9	}
 10	
 11	function help(programName) {
 12	  return `${usage(programName)}
 13	
 14	options:
 15	  -h, --help            show this help message and exit
 16	  --subject SUBJECT
 17	  --user_data USER_DATA`;
 18	}
 19	
 20	function requiredMessage(programName, missing) {
 21	  return `${usage(programName)}
 22	${programName}: error: the following arguments are required: ${missing.join(', ')}`;
 23	}
 24	
 25	function expectedValueMessage(programName, optionName) {
 26	  return `${usage(programName)}
 27	${programName}: error: argument ${optionName}: expected one argument`;
 28	}
 29	
 30	function unrecognizedMessage(programName, extras) {
 31	  return `${usage(programName)}
 32	${programName}: error: unrecognized arguments: ${extras.join(' ')}`;
 33	}
