 35	function parseInlineValue(token, optionName) {
 36	  const prefix = `${optionName}=`;
 37	  if (!token.startsWith(prefix)) {
 38	    return null;
 39	  }
 40	
 41	  return token.slice(prefix.length);
 42	}
