 44	export function parseArgs(argv, scriptPath) {
 45	  const programName = basename(scriptPath);
 46	  const values = {
 47	    subject: undefined,
 48	    user_data: undefined,
 49	  };
 50	  const extras = [];
 51	
 52	  for (let index = 0; index < argv.length; index += 1) {
 53	    const token = argv[index];
 54	
 55	    if (token === '-h' || token === '--help') {
 56	      return {
 57	        kind: 'help',
 58	        text: help(programName),
 59	        exitCode: 0,
 60	      };
 61	    }
 62	
 63	    const inlineSubject = parseInlineValue(token, '--subject');
 64	    if (inlineSubject !== null) {
 65	      values.subject = inlineSubject;
 66	      continue;
 67	    }
 68	
 69	    const inlineUserData = parseInlineValue(token, '--user_data');
 70	    if (inlineUserData !== null) {
 71	      values.user_data = inlineUserData;
 72	      continue;
 73	    }
 74	
 75	    if (token === '--subject' || token === '--user_data') {
 76	      const next = argv[index + 1];
 77	
 78	      if (next === undefined || next.startsWith('-')) {
 79	        return {
 80	          kind: 'error',
 81	          text: expectedValueMessage(programName, token),
 82	          exitCode: 2,
 83	        };
 84	      }
 85	
 86	      if (token === '--subject') {
 87	        values.subject = next;
 88	      } else {
 89	        values.user_data = next;
 90	      }
 91	
 92	      index += 1;
 93	      continue;
 94	    }
 95	
 96	    extras.push(token);
 97	  }
 98	
 99	  const missing = [];
100	  if (values.subject === undefined) {
101	    missing.push('--subject');
102	  }
103	  if (values.user_data === undefined) {
104	    missing.push('--user_data');
105	  }
106	
107	  if (missing.length > 0) {
108	    return {
109	      kind: 'error',
110	      text: requiredMessage(programName, missing),
111	      exitCode: 2,
112	    };
113	  }
114	
115	  if (extras.length > 0) {
116	    return {
117	      kind: 'error',
118	      text: unrecognizedMessage(programName, extras),
119	      exitCode: 2,
120	    };
121	  }
122	
123	  return {
124	    kind: 'ok',
125	    values,
126	    exitCode: 0,
127	  };
128	}

