17	async function signSegments(headerSegment, payloadSegment, secret) {
18	  const signingInput = `${headerSegment}.${payloadSegment}`;
19	  const signatureBytes = await signHmacSha256(signingInput, secret);
20	  return encodeBase64UrlFromBytes(signatureBytes);
