23	export async function encodeJwt(payload, secret) {
24	  const header = {
25	    alg: 'HS256',
26	    typ: 'JWT',
27	  };
28	  const headerSegment = encodeBase64UrlFromText(serializeJson(header));
29	  const payloadSegment = encodeBase64UrlFromText(serializeJson(payload));
30	  const signatureSegment = await signSegments(headerSegment, payloadSegment, secret);
31	  return `${headerSegment}.${payloadSegment}.${signatureSegment}`;
32	}
