34	export async function decodeJwt(token, secret, { options = {}, algorithms = [] } = {}) {
35	  const parts = token.split('.');
36	  if (parts.length !== 3) {
37	    throw new Error('Not enough segments');
38	  }
39	
40	  const [headerSegment, payloadSegment, signatureSegment] = parts;
41	  const header = parseJson(decodeBase64UrlToText(headerSegment));
42	  const payload = parseJson(decodeBase64UrlToText(payloadSegment));
43	
44	  if (algorithms.length > 0 && !algorithms.includes(header.alg)) {
45	    throw new Error('The specified alg value is not allowed');
46	  }
47	
48	  const expectedSignature = await signSegments(headerSegment, payloadSegment, secret);
49	  const actualBytes = decodeBase64UrlToBytes(signatureSegment);
50	  const expectedBytes = decodeBase64UrlToBytes(expectedSignature);
51	
52	  if (!timingSafeEqual(actualBytes, expectedBytes)) {
53	    throw new Error('Signature verification failed');
54	  }
55	
56	  if (options.verify_sub && payload.sub !== undefined && typeof payload.sub !== 'string') {
57	    throw new Error('Subject must be a string');
58	  }
59	
60	  return payload;
61	}
